package com.cybershield.controller;
import com.cybershield.model.*; import com.cybershield.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/incidents/{incidentId}/evidence") public class EvidenceController { final EvidenceRepository repo;final IncidentRepository incidents;final UserRepository users; @Value("${app.upload-dir}") String dir; public EvidenceController(EvidenceRepository r,IncidentRepository i,UserRepository u){repo=r;incidents=i;users=u;} Incident permittedIncident(Long id,Authentication auth){Incident i=incidents.findById(id).orElseThrow();User u=users.findByEmail(auth.getName()).orElseThrow();if(u.getRole()==Role.ADMIN||i.getReporter().getId().equals(u.getId())||(i.getAssignee()!=null&&i.getAssignee().getId().equals(u.getId())))return i;throw new AccessDeniedException("Incident access denied");} @GetMapping List<Evidence> all(@PathVariable Long incidentId,Authentication a){permittedIncident(incidentId,a);return repo.findByIncidentIdOrderByUploadedAtDesc(incidentId);} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) Evidence upload(@PathVariable Long incidentId,@RequestPart MultipartFile file,Authentication a)throws Exception{Incident i=permittedIncident(incidentId,a);if(file.isEmpty()||file.getSize()>20L*1024*1024)throw new IllegalArgumentException("Evidence file must be non-empty and no larger than 20 MB");String original=Optional.ofNullable(file.getOriginalFilename()).orElse("evidence");String ext=original.contains(".")?original.substring(original.lastIndexOf('.')).toLowerCase(Locale.ROOT):"";if(!Set.of(".txt",".log",".csv",".json",".png",".jpg",".jpeg",".pdf").contains(ext))throw new IllegalArgumentException("Unsupported evidence file type");Path root=Paths.get(dir).toAbsolutePath().normalize();Files.createDirectories(root);String stored=UUID.randomUUID()+ext;Path target=root.resolve(stored).normalize();if(!target.startsWith(root))throw new IllegalArgumentException("Invalid storage path");Files.copy(file.getInputStream(),target);Evidence e=new Evidence();e.setIncident(i);e.setOriginalName(original.replaceAll("[\\r\\n\\\"]","_"));e.setStoredName(stored);e.setContentType("application/octet-stream");e.setSizeBytes(file.getSize());e.setUploadedBy(users.findByEmail(a.getName()).orElseThrow());return repo.save(e);} @GetMapping("/{evidenceId}/download") ResponseEntity<Resource> download(@PathVariable Long incidentId,@PathVariable Long evidenceId,Authentication a)throws Exception{permittedIncident(incidentId,a);Evidence e=repo.findByIdAndIncidentId(evidenceId,incidentId).orElseThrow();Path root=Paths.get(dir).toAbsolutePath().normalize(),file=root.resolve(e.getStoredName()).normalize();if(!file.startsWith(root)||!Files.isRegularFile(file))throw new IllegalArgumentException("Evidence not found");Resource r=new FileSystemResource(file);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+e.getOriginalName()+"\"").contentType(MediaType.APPLICATION_OCTET_STREAM).body(r);} }
